import os
import requests

def fetch_recent_logs(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["LOGDNA_API_KEY"]
    app = config.get("app") or os.environ["LOGDNA_APP"]
    url = f"https://api.logdna.com/v1/{app}/query"
    params = {}

    if "from" in payload:
        params["from"] = payload["from"]
    elif "start" in payload:
        params["from"] = payload["start"]

    if "to" in payload:
        params["to"] = payload["to"]
    elif "end" in payload:
        params["to"] = payload["end"]

    if "query" in payload:
        params["query"] = payload["query"]

    field_filters = payload.get("fields") or payload.get("filters") or {}
    if field_filters:
        parts = []
        for key, value in field_filters.items():
            if isinstance(value, (list, tuple, set)):
                or_parts = [f'{key}:"{str(v)}"' for v in value]
                parts.append("(" + " OR ".join(or_parts) + ")")
            else:
                parts.append(f'{key}:"{str(value)}"')
        filter_query = " AND ".join(parts)
        if params.get("query"):
            params["query"] = f'({params["query"]}) AND {filter_query}'
        else:
            params["query"] = filter_query

    if "limit" in payload:
        params["limit"] = payload["limit"]

    if "offset" in payload:
        params["offset"] = payload["offset"]

    if "sort" in payload:
        params["sort"] = payload["sort"]

    response = requests.get(
        url,
        params=params,
        headers={"apikey": api_key, "accept": "application/json"},
        timeout=config.get("timeout", 30),
    )
    response.raise_for_status()
    data = response.json()
    result = data.get("results", data)
    return result
